window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2195f931acff1645"]={"versions": [{"id": "FIG-2195f931acff1645", "releases": ["R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> SPEM 2.0 (Software & Systems Process Engineering Metamodel) Prozess- und Aktivitätsdiagramm.</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des methodischen E2E-Workflows für den Use Case „Trace-basierte Timing-Verifikation einer verteilten Implementierung“ gemäß <code>AUTOSAR_FO_TR_TimingAnalysis</code> (Foundation, R23-11/R24-11). Das Diagramm definiert den prozessualen Übergang von realen Ausführungsartefakten verteilter Systeme (Busse, ECUs) über empirische Messergebnisse hin zum formalen Soll-Ist-Abgleich gegen die im AUTOSAR-Systemmodell spezifizierten Timing-Vorgaben.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### SPEM Tasks (Aktivitäten / Operationen)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Perform Implementation-Based Timing Analysis</code>:</strong> Tool- und hardwaregestützte Extraktion empirischer Laufzeit- und Kommunikationsmetriken aus der realen Zielumgebung (z. B. Auswertung von Trace-Events, Triggern, Task-Starts/-Stopps, Bus-Frames).</li>\n<li><strong><code>Verify Timing</code>:</strong> Automatisierter oder teilautomatisierter mathematisch-logischer Abgleich zwischen gemessenen Ist-Metriken und definierten Soll-Budgets.</li>\n</ul>\n<p class=\"fig-p\">#### SPEM Work Products (Artefakte / Datenstrukturen)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Implementation</code>:</strong> Physische Gesamtimplementierung bestehend aus kompilierter Target-Software (Classic/Adaptive Plattform, BSW, RTE, SW-Cs), Steuergeräte-Hardware, Netzwerktopologie (CAN, FlexRay, Ethernet) und Messinstrumentierung.</li>\n<li><strong><code>Timing Requirements</code>:</strong> Spezifizierte Timing-Vorgaben, formalisiert über AUTOSAR Timing Extensions (<code>TIMEX</code> in ARXML, z. B. <code>LatencyTimingConstraint</code>, <code>EventChain</code>, <code>ExecutionTimeConstraint</code>).</li>\n<li><strong><code>Timing Analysis Report</code>:</strong> Aggregierte Analyseergebnisse der gemessenen Implementierung (z. B. Worst-Case Response Times, Task-Jitter, Bus-Arbitrierungszeiten, Scheduling-Gaps).</li>\n<li><strong><code>Timing Verification Report</code>:</strong> Konformitäts- und Freigabedokument mit Statusbewertung (Pass/Fail, Margins, Identifikation verletzter Constraints).</li>\n</ul>\n<p class=\"fig-p\">#### Stereotypen, gerichtete Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><code>Implementation</code> $\\xrightarrow{\\text{«input»\\ [1]}}$ <code>Perform Implementation-Based Timing Analysis</code></li>\n<li><code>Perform Implementation-Based Timing Analysis</code> $\\xrightarrow{\\text{«output»\\ [1]}}$ <code>Timing Analysis Report</code></li>\n<li><code>Timing Analysis Report</code> $\\xrightarrow{\\text{«input»\\ [1]}}$ <code>Verify Timing</code></li>\n<li><code>Timing Requirements</code> $\\xrightarrow{\\text{«input»\\ [1]}}$ <code>Verify Timing</code></li>\n<li><code>Verify Timing</code> $\\xrightarrow{\\text{«output»\\ [1]}}$ <code>Timing Verification Report</code></li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Datenerfassung & Timing-Analyse (Phase 1):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Eingang:</em> Bereitstellung der ablauffähigen <code>Implementation</code> auf dem Target/HIL.</li>\n<li><em>Ablauf:</em> Instrumentierte Ausführung oder Hardware-Tracing (z. B. via CoreSight, Nexus, ARTI/ORTI oder Bus-Monitor). <code>Perform Implementation-Based Timing Analysis</code> rekonstruiert die kausalen Event-Ketten (Sensor $\\rightarrow$ RTE $\\rightarrow$ Com $\\rightarrow$ Bus $\\rightarrow$ Com $\\rightarrow$ RTE $\\rightarrow$ Aktuator).</li>\n<li><em>Ausgang:</em> Generierung des <code>Timing Analysis Report</code> mit konkreten Zeitstempeln und gemessenen Latenzen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Timing-Verifikation (Phase 2):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Eingang:</em> Synchrones Zuführen des <code>Timing Analysis Report</code> und der formalen <code>Timing Requirements</code>.</li>\n<li><em>Ablauf:</em> <code>Verify Timing</code> prüft E2E-Latenzen ($t_{\\text{measured}} \\le t_{\\text{deadline}}$), Periodizitäten und Jitter-Schranken ab.</li>\n<li><em>Ausgang:</em> Erzeugung des <code>Timing Verification Report</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abbruch- und Rückkopplungspfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ergibt die Verifikation Verletzungen (Fail), triggert der Report eine Rekonfiguration des Task-Schedulings (OS), der RTE-Event-Mappings oder der Netzwerk-PDU-Planung.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Trace-Infrastruktur & ARTI/ORTI:</strong> Für die Erzeugung verwertbarer Traces müssen Entwickler standardisierte Schnittstellen vorhalten: OS-Hooks (<code>PreTaskHook</code>, <code>PostTaskHook</code>), RTE-Vf-Hooks (<code>Rte_Runnable_Start</code>, <code>Rte_Runnable_Return</code>) oder AUTOSAR Run-Time Interface (ARTI) Tracing Points.</li>\n<li><strong>Globale Zeitbasis bei verteilten Systemen:</strong> Zur Verifikation verteilter Event-Chains über Steuergerätegrenzen hinweg ist eine strikte Uhrensynchronisation zwingend erforderlich (z. B. via <code>StbM</code> [Synchronized Time-Base Manager] in Verbindung mit <code>EthTSyn</code> [IEEE 802.1AS/PTP], <code>CanTSyn</code> oder <code>FrTSyn</code>). Ohne konsistente globale Zeitstempel sind E2E-Latenzanalysen ungültig.</li>\n<li><strong>Probe-Effekt (Intrusiveness):</strong> Softwarebasierte Mess-Hooks verändern das Ausführungsverhalten (Execution Time, Cache-Hits). Wo möglich, sind hardwaregestützte, nicht-intrusive Traces einzusetzen, um verfälschte Messwerte im <code>Timing Analysis Report</code> auszuschließen.</li>\n<li><strong>Sicherheitsnachweis nach ISO 26262:</strong> Der <code>Timing Verification Report</code> dient als normativer Nachweis der zeitlichen Unabhängigkeit (Freedom from Interference in time domain) und Validierung der Sicherheitsziele (Safety Goals) bezüglich E2E-Latenzen.</li>\n</ul>"}, {"id": "FIG-95d6df37d9c02b24", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> SPEM 2.0 (Software & Systems Process Engineering Metamodel) Prozess- und Aktivitätsdiagramm.</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des methodischen E2E-Workflows für den Use Case „Trace-basierte Timing-Verifikation einer verteilten Implementierung“ gemäß <code>AUTOSAR_FO_TR_TimingAnalysis</code> (Foundation, R23-11/R24-11). Das Diagramm definiert den prozessualen Übergang von realen Ausführungsartefakten verteilter Systeme (Busse, ECUs) über empirische Messergebnisse hin zum formalen Soll-Ist-Abgleich gegen die im AUTOSAR-Systemmodell spezifizierten Timing-Vorgaben.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### SPEM Tasks (Aktivitäten / Operationen)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Perform Implementation-Based Timing Analysis</code>:</strong> Tool- und hardwaregestützte Extraktion empirischer Laufzeit- und Kommunikationsmetriken aus der realen Zielumgebung (z. B. Auswertung von Trace-Events, Triggern, Task-Starts/-Stopps, Bus-Frames).</li>\n<li><strong><code>Verify Timing</code>:</strong> Automatisierter oder teilautomatisierter mathematisch-logischer Abgleich zwischen gemessenen Ist-Metriken und definierten Soll-Budgets.</li>\n</ul>\n<p class=\"fig-p\">#### SPEM Work Products (Artefakte / Datenstrukturen)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Implementation</code>:</strong> Physische Gesamtimplementierung bestehend aus kompilierter Target-Software (Classic/Adaptive Plattform, BSW, RTE, SW-Cs), Steuergeräte-Hardware, Netzwerktopologie (CAN, FlexRay, Ethernet) und Messinstrumentierung.</li>\n<li><strong><code>Timing Requirements</code>:</strong> Spezifizierte Timing-Vorgaben, formalisiert über AUTOSAR Timing Extensions (<code>TIMEX</code> in ARXML, z. B. <code>LatencyTimingConstraint</code>, <code>EventChain</code>, <code>ExecutionTimeConstraint</code>).</li>\n<li><strong><code>Timing Analysis Report</code>:</strong> Aggregierte Analyseergebnisse der gemessenen Implementierung (z. B. Worst-Case Response Times, Task-Jitter, Bus-Arbitrierungszeiten, Scheduling-Gaps).</li>\n<li><strong><code>Timing Verification Report</code>:</strong> Konformitäts- und Freigabedokument mit Statusbewertung (Pass/Fail, Margins, Identifikation verletzter Constraints).</li>\n</ul>\n<p class=\"fig-p\">#### Stereotypen, gerichtete Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><code>Implementation</code> $\\xrightarrow{\\text{«input»\\ [1]}}$ <code>Perform Implementation-Based Timing Analysis</code></li>\n<li><code>Perform Implementation-Based Timing Analysis</code> $\\xrightarrow{\\text{«output»\\ [1]}}$ <code>Timing Analysis Report</code></li>\n<li><code>Timing Analysis Report</code> $\\xrightarrow{\\text{«input»\\ [1]}}$ <code>Verify Timing</code></li>\n<li><code>Timing Requirements</code> $\\xrightarrow{\\text{«input»\\ [1]}}$ <code>Verify Timing</code></li>\n<li><code>Verify Timing</code> $\\xrightarrow{\\text{«output»\\ [1]}}$ <code>Timing Verification Report</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Datenerfassung & Timing-Analyse (Phase 1):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Eingang:</em> Bereitstellung der ablauffähigen <code>Implementation</code> auf dem Target/HIL.</li>\n<li><em>Ablauf:</em> Instrumentierte Ausführung oder Hardware-Tracing (z. B. via CoreSight, Nexus, ARTI/ORTI oder Bus-Monitor). <code>Perform Implementation-Based Timing Analysis</code> rekonstruiert die kausalen Event-Ketten (Sensor $\\rightarrow$ RTE $\\rightarrow$ Com $\\rightarrow$ Bus $\\rightarrow$ Com $\\rightarrow$ RTE $\\rightarrow$ Aktuator).</li>\n<li><em>Ausgang:</em> Generierung des <code>Timing Analysis Report</code> mit konkreten Zeitstempeln und gemessenen Latenzen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Timing-Verifikation (Phase 2):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Eingang:</em> Synchrones Zuführen des <code>Timing Analysis Report</code> und der formalen <code>Timing Requirements</code>.</li>\n<li><em>Ablauf:</em> <code>Verify Timing</code> prüft E2E-Latenzen ($t_{\\text{measured}} \\le t_{\\text{deadline}}$), Periodizitäten und Jitter-Schranken ab.</li>\n<li><em>Ausgang:</em> Erzeugung des <code>Timing Verification Report</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abbruch- und Rückkopplungspfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ergibt die Verifikation Verletzungen (Fail), triggert der Report eine Rekonfiguration des Task-Schedulings (OS), der RTE-Event-Mappings oder der Netzwerk-PDU-Planung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Trace-Infrastruktur & ARTI/ORTI:</strong> Für die Erzeugung verwertbarer Traces müssen Entwickler standardisierte Schnittstellen vorhalten: OS-Hooks (<code>PreTaskHook</code>, <code>PostTaskHook</code>), RTE-Vf-Hooks (<code>Rte_Runnable_Start</code>, <code>Rte_Runnable_Return</code>) oder AUTOSAR Run-Time Interface (ARTI) Tracing Points.</li>\n<li><strong>Globale Zeitbasis bei verteilten Systemen:</strong> Zur Verifikation verteilter Event-Chains über Steuergerätegrenzen hinweg ist eine strikte Uhrensynchronisation zwingend erforderlich (z. B. via <code>StbM</code> [Synchronized Time-Base Manager] in Verbindung mit <code>EthTSyn</code> [IEEE 802.1AS/PTP], <code>CanTSyn</code> oder <code>FrTSyn</code>). Ohne konsistente globale Zeitstempel sind E2E-Latenzanalysen ungültig.</li>\n<li><strong>Probe-Effekt (Intrusiveness):</strong> Softwarebasierte Mess-Hooks verändern das Ausführungsverhalten (Execution Time, Cache-Hits). Wo möglich, sind hardwaregestützte, nicht-intrusive Traces einzusetzen, um verfälschte Messwerte im <code>Timing Analysis Report</code> auszuschließen.</li>\n<li><strong>Sicherheitsnachweis nach ISO 26262:</strong> Der <code>Timing Verification Report</code> dient als normativer Nachweis der zeitlichen Unabhängigkeit (Freedom from Interference in time domain) und Validierung der Sicherheitsziele (Safety Goals) bezüglich E2E-Latenzen.</li>\n</ul>"}], "trans": [{"from": "FIG-2195f931acff1645", "to": "FIG-95d6df37d9c02b24", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
